// Автогенерировано Tools/build_stage1_pbr_pack.py (CC0 Poly Haven Photogrammetry + Pure Sky HDRI Tonemapped)
// Реальные фототекстуры скал (rock_face_03), альпийского дёрна (aerial_grass_rock),
// лесной грязи (brown_mud_leaves_01), кладки дикого камня (castle_brick_broken_06) и горного неба с облаками.
import * as THREE from 'three';
import { GTAOPass } from 'three/examples/jsm/postprocessing/GTAOPass.js';

export const PBR_ROCK_DIFF_URI = 'data:image/jpeg;base64,';
export const PBR_ROCK_NOR_URI = 'data:image/jpeg;base64,';
export const PBR_ROCK_ARM_URI = 'data:image/jpeg;base64,';
export const PBR_GRASS_DIFF_URI = 'data:image/jpeg;base64,';
export const PBR_GRASS_NOR_URI = 'data:image/jpeg;base64,';
export const PBR_MUD_DIFF_URI = 'data:image/jpeg;base64,';
export const PBR_MUD_NOR_URI = 'data:image/jpeg;base64,';
export const PBR_MASONRY_DIFF_URI = 'data:image/jpeg;base64,';
export const PBR_MASONRY_NOR_URI = 'data:image/jpeg;base64,';
export const PBR_MASONRY_ARM_URI = 'data:image/jpeg;base64,';
export const PBR_SKY_EQUIRECT_URI = 'data:image/jpeg;base64,';

function createFallbackSkyDataTexture() {
  const w = 64;
  const h = 32;
  const data = new Uint8Array(w * h * 4);
  for (let y = 0; y < h; y++) {
    const v = y / (h - 1);
    let r;
    let g;
    let b;
    if (v > 0.52) {
      const t = (v - 0.52) / 0.48;
      r = Math.round(168 - t * 105);
      g = Math.round(198 - t * 88);
      b = Math.round(225 - t * 45);
    } else if (v > 0.45) {
      const t = (v - 0.45) / 0.07;
      r = Math.round(92 + t * 76);
      g = Math.round(86 + t * 112);
      b = Math.round(74 + t * 151);
    } else {
      r = 68;
      g = 62;
      b = 52;
    }
    for (let x = 0; x < w; x++) {
      const idx = (y * w + x) * 4;
      data[idx] = r;
      data[idx + 1] = g;
      data[idx + 2] = b;
      data[idx + 3] = 255;
    }
  }
  const tex = new THREE.DataTexture(data, w, h, THREE.RGBAFormat);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.mapping = THREE.EquirectangularReflectionMapping;
  tex.minFilter = THREE.LinearFilter;
  tex.magFilter = THREE.LinearFilter;
  tex.generateMipmaps = false;
  tex.needsUpdate = true;
  return tex;
}

/**
 * Создаёт свежий комплект PBR-текстур и PMREM-карту освещения IBL для конкретного WebGLRenderer.
 * Каждый viewport владеет своими текстурами и обязан вызвать pack.dispose() при размонтировании.
 */
export function loadCaucasusPbrPack(renderer, { onSkyReady } = {}) {
  const maxAniso = Math.min(8, renderer?.capabilities?.getMaxAnisotropy?.() || 4);
  const ownedTextures = [];
  let disposed = false;

  const makeRepeatTex = (uri, isColor = true) => {
    const img = new Image();
    const tex = new THREE.Texture(img);
    tex.wrapS = THREE.RepeatWrapping;
    tex.wrapT = THREE.RepeatWrapping;
    tex.colorSpace = isColor ? THREE.SRGBColorSpace : THREE.NoColorSpace;
    tex.anisotropy = maxAniso;
    tex.minFilter = THREE.LinearMipmapLinearFilter;
    tex.magFilter = THREE.LinearFilter;
    tex.generateMipmaps = true;
    img.onload = () => {
      if (!disposed) tex.needsUpdate = true;
    };
    img.src = uri;
    ownedTextures.push(tex);
    return tex;
  };

  const rockDiff = makeRepeatTex(PBR_ROCK_DIFF_URI, true);
  const rockNor = makeRepeatTex(PBR_ROCK_NOR_URI, false);
  const rockArm = makeRepeatTex(PBR_ROCK_ARM_URI, false);
  const grassDiff = makeRepeatTex(PBR_GRASS_DIFF_URI, true);
  const grassNor = makeRepeatTex(PBR_GRASS_NOR_URI, false);
  const mudDiff = makeRepeatTex(PBR_MUD_DIFF_URI, true);
  const mudNor = makeRepeatTex(PBR_MUD_NOR_URI, false);
  const masonryDiff = makeRepeatTex(PBR_MASONRY_DIFF_URI, true);
  const masonryNor = makeRepeatTex(PBR_MASONRY_NOR_URI, false);
  const masonryArm = makeRepeatTex(PBR_MASONRY_ARM_URI, false);

  const fallbackEquirect = createFallbackSkyDataTexture();
  ownedTextures.push(fallbackEquirect);

  let pmrem = new THREE.PMREMGenerator(renderer);
  pmrem.compileEquirectangularShader();
  let envRT = pmrem.fromEquirectangular(fallbackEquirect);

  // Отключаем мипмапы у equirectangular неба (wrapS Repeat + LinearFilter), чтобы убрать 1px шов atan() на горизонте
  const skyImg = new Image();
  const skyEquirectTex = new THREE.Texture(skyImg);
  skyEquirectTex.colorSpace = THREE.SRGBColorSpace;
  skyEquirectTex.mapping = THREE.EquirectangularReflectionMapping;
  skyEquirectTex.wrapS = THREE.RepeatWrapping;
  skyEquirectTex.wrapT = THREE.ClampToEdgeWrapping;
  skyEquirectTex.generateMipmaps = false;
  skyEquirectTex.minFilter = THREE.LinearFilter;
  skyEquirectTex.magFilter = THREE.LinearFilter;
  ownedTextures.push(skyEquirectTex);

  const pack = {
    rockDiff,
    rockNor,
    rockArm,
    grassDiff,
    grassNor,
    mudDiff,
    mudNor,
    masonryDiff,
    masonryNor,
    masonryArm,
    skyEquirectTex,
    envMap: envRT.texture,
    dispose: () => {
      disposed = true;
      if (pmrem) {
        pmrem.dispose();
        pmrem = null;
      }
      if (envRT) {
        envRT.dispose();
        envRT = null;
      }
      ownedTextures.forEach((tx) => tx.dispose());
    }
  };

  skyImg.onload = () => {
    if (disposed || !pmrem) return;
    skyEquirectTex.needsUpdate = true;
    try {
      const nextEnvRT = pmrem.fromEquirectangular(skyEquirectTex);
      if (disposed) {
        nextEnvRT.dispose();
        return;
      }
      const prevEnvRT = envRT;
      envRT = nextEnvRT;
      pack.envMap = nextEnvRT.texture;
      if (prevEnvRT) prevEnvRT.dispose();
      pmrem.dispose();
      pmrem = null;
      if (onSkyReady) onSkyReady(pack);
    } catch {
      if (pmrem) {
        pmrem.dispose();
        pmrem = null;
      }
    }
  };
  skyImg.src = PBR_SKY_EQUIRECT_URI;

  return pack;
}

/**
 * Подключает GTAOPass для контактных теней с автоматическим исключением
 * полупрозрачных спрайтов тумана, водных лент и частиц из depth/normal буфера.
 */
export function attachCleanGtaoPass({
  scene,
  camera,
  composer,
  width,
  height,
  clipBox,
  blendIntensity = 0.76,
  radius = 0.76,
  distanceExponent = 1.45,
  thickness = 0.9,
  samples = 12
}) {
  try {
    const gtaoPass = new GTAOPass(
      scene,
      camera,
      Math.max(256, Math.round(width * 0.75)),
      Math.max(256, Math.round(height * 0.75))
    );
    gtaoPass.output = GTAOPass.OUTPUT.Default;
    gtaoPass.blendIntensity = blendIntensity;
    gtaoPass.updateGtaoMaterial({
      radius,
      distanceExponent,
      thickness,
      scale: 1.0,
      samples
    });
    if (clipBox) gtaoPass.setSceneClipBox(clipBox);
    composer.addPass(gtaoPass);

    const hiddenForGtao = [];
    const origGtaoRender = gtaoPass.render.bind(gtaoPass);
    gtaoPass.render = (...args) => {
      hiddenForGtao.length = 0;
      scene.traverse((obj) => {
        if (!obj.visible) return;
        const mat = Array.isArray(obj.material) ? obj.material[0] : obj.material;
        if (
          obj.isSprite ||
          obj.isPoints ||
          obj.userData?.excludeFromGtao ||
          (mat && ((mat.transparent && mat.depthWrite === false) || mat.alphaTest > 0))
        ) {
          obj.visible = false;
          hiddenForGtao.push(obj);
        }
      });
      try {
        origGtaoRender(...args);
      } finally {
        for (let i = 0; i < hiddenForGtao.length; i++) hiddenForGtao[i].visible = true;
      }
    };
    return gtaoPass;
  } catch {
    return null;
  }
}
